              wonder_trade = "observe",
              pokemon_identity = "delegate",
              species_metadata = "delegate",
              item_use = "compose",
              shopping = "compose",
              healing = "compose",
              battle_finish = "compose",
              trainer_card = "compose",
              party_menu = "compose",
              start_menu_items = "compose",
