  function mod.exports.__beta26.ruleForConfigSurface(rule, goldMode)
      if not goldMode then
          if rule and rule.goldOnly == true then return nil end
          return rule
      end
      if not (rule and mod.exports.__beta26.goldBetaRules[rule.key]) then return nil end
      local copy = {}
      for k, v in pairs(rule) do copy[k] = v end
      copy.desc = mod.exports.__beta26.goldBetaDescriptions[rule.key] or copy.desc
      return copy
  end

  ---------------------------------------------------------------------
  -- FLAT RULE LIST
  -- QoL owns convenience resources and startup kits. Gym Guide Rare Candy
  -- remains live during setup and active play; starting Money/Balls/Candies,
  -- PC Heal Items, and PC Vitamins are fresh-save-only controls.
  ---------------------------------------------------------------------
  local function buildFlatItemList(preGame, goldMode)
      local list = {}

      do
          table.insert(list, {
              isHeader = false, isControl = true, isLockeTypeControl = true,
              rule = {
                  key = "locke_type", name = Strings.source("Nuzlocke Loadout"), shortName = Strings.source("Nuz. Loadout"),
                  desc = Strings.source("Choose only the Nuzlocke ruleset. CUSTOM keeps manual settings; NUZ is standard; HARD adds Champion caps plus battle healing/X-item restrictions; SOLO adds Solo Only + Whiteout; IRON is an IronMON-style solo/no-heal/no-shop challenge using rules this mod owns. Independent from Game Difficulty.")
              }
          })
      end

      table.insert(list, {
          isHeader = false, isControl = true, isRuleLockControl = true,
          rule = {
              key = "rule_lock", name = Strings.source("Rule Lock"),
              desc = Strings.source("Temporarily lock challenge-rule editing to prevent accidental changes. Unlike Permanent Rule Seal, Rule Lock can be turned OFF again at any time. Game Difficulty, World Building, QoL, and presentation controls remain independently adjustable while locked.")
          }
      })

      table.insert(list, {
          isHeader = false, isControl = true,
          rule = {
              key = "rules_locked", name = Strings.source("Permanent Rule Seal"),
              desc = Strings.source("WIP: Permanent Rule Seal is temporarily disabled and cannot be selected. The implementation and prior test markers are preserved for recovery, but no seal is enforced while this feature is WIP.")
          }
      })

      for _, cat in ipairs(ruleCategories) do
          local visible = {}
          for _, rule in ipairs(cat.rules) do
              local r = mod.exports.__beta26.ruleForConfigSurface(rule, goldMode)
              if r and (preGame or r.setupOnly ~= true) then
                  visible[#visible + 1] = r
              end
          end
          if #visible > 0 then
              table.insert(list, { isHeader = true, name = cat.title, shortName = cat.shortTitle })
              for _, rule in ipairs(visible) do
                  table.insert(list, { isHeader = false, rule = rule })
              end
          end
      end

      if not preGame then
          table.insert(list, {
              isHeader = false, isControl = true, isInGameSave = true,
              alwaysVisible = true,
              rule = { key = "save_in_game_rules", name = Strings.source("Save Rules"),
                  desc = goldMode
                      and Strings.source("Save the current GOLD BETA-compatible settings to the active Gold save.")
                      or Strings.source("Save the current NUZLOCKE RULES to the active game save.") }
          })
          if not goldMode then
              table.insert(list, {
                  isHeader = false, isControl = true, isRecoveryControl = true,
                  alwaysVisible = true,
                  rule = { key = "recover_legacy_catches", name = Strings.source("Recover Catches"),
                      desc = Strings.source("Review Pokemon from older saves whose catch location could not be recovered automatically.") }
              })
          end
      end

      if preGame then
          table.insert(list, { isHeader = false, isControl = true, isSetupSave = true,
              alwaysVisible = true,
              rule = { key = "save_setup_options", name = Strings.source("Save Setup"),
                  desc = goldMode
                      and Strings.source("Save this separate GOLD BETA profile for the next Gold NEW GAME. It does not replace the R/B/Y profile.")
                      or Strings.source("Save this separate R/B/Y profile for the next Gen1 NEW GAME. It does not replace the Gold profile.") } })
      end
      return list
  end


